下面的函数按 `名称:数值` 的格式汇总记录：
```go
func summarize(records []string) (map[string][]int, error) {
    result := make(map[string][]int)
    for i, r := range records {
        parts := strings.Split(r, ":")
        if len(parts) != 2 {
            return nil, fmt.Errorf("第 %d 条记录格式错误: %q", i, r)
        }
        n, err := strconv.Atoi(parts[1])
        if err != nil {
            return nil, fmt.Errorf("第 %d 条记录数值非法: %w", i, err)
        }
        result[parts[0]] = append(result[parts[0]], n)
    }
    return result, nil
}
```
