阅读下面的代码，`sumAll([]int{1, 2, -3, 4})` 返回什么？
```go
var ErrNegative = errors.New("负数")

type Accumulator struct {
    total int
}

func (a *Accumulator) Add(n int) error {
    if n < 0 {
        return fmt.Errorf("负数 %d: %w", n, ErrNegative)
    }
    a.total += n
    return nil
}

func sumAll(nums []int) (acc Accumulator, err error) {
    defer func() {
        if err != nil {
            acc = Accumulator{}
        }
    }()
    for _, n := range nums {
        if e := acc.Add(n); e != nil {
            return acc, e
        }
    }
    return acc, nil
}
```
